<?php
require_once dirname(__DIR__).'/includes/bootstrap.php'; require_module('budget');
$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM budgets WHERE id=?');$s->execute([$id]);$b=$s->fetch();if(!$b){flash('danger','Budget not found.');redirect('budget/index.php');}
$pageTitle='Edit Budget';$activeMenu='budget-list';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$year=(int)$_POST['budget_year'];$dept=(int)$_POST['department_id'];$cat=(int)$_POST['category_id'];$desc=trim($_POST['description']);$amount=(float)$_POST['allocated_amount'];if(!$dept||!$cat||$desc===''||$amount<=0)$errors[]='Please complete all required fields with valid values.';if(!$errors){$u=db()->prepare("UPDATE budgets SET budget_year=?,department_id=?,category_id=?,description=?,allocated_amount=?,approval_status='Pending',updated_at=NOW() WHERE id=?");$u->execute([$year,$dept,$cat,$desc,$amount,$id]);$a=db()->prepare("SELECT id FROM approvals WHERE request_type='budget' AND request_id=? LIMIT 1");$a->execute([$id]);$aid=$a->fetchColumn();if($aid){db()->prepare("UPDATE approvals SET current_stage='department_manager',status='Pending',remarks=NULL,updated_at=NOW() WHERE id=?")->execute([$aid]);db()->prepare("INSERT INTO approval_history(approval_id,stage,action,action_by,remarks) VALUES(?,'request','Resubmitted',?,'Budget edited and resubmitted')")->execute([$aid,current_user()['id']]);}else save_approval_request('budget',$id);log_activity('UPDATE','Budget','Edited '.$b['budget_code']);flash('success','Budget updated and resubmitted for approval.');redirect('budget/index.php');}}
$departments=departments();$categories=categories();require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><h1>Edit Budget</h1><p><?= e($b['budget_code']) ?> · Editing sends the budget back through approval.</p></div><a href="<?= e(url('budget/index.php')) ?>" class="btn btn-light border">Back</a></div><?php if($errors):?><div class="alert alert-danger"><?= e(implode(' ',$errors)) ?></div><?php endif; ?><div class="card-panel"><div class="card-body"><form method="post"><?= csrf_field() ?><div class="row g-3"><div class="col-md-4"><label class="form-label">Budget Year</label><input class="form-control" type="number" name="budget_year" value="<?= e($_POST['budget_year']??$b['budget_year']) ?>" required></div><div class="col-md-4"><label class="form-label">Department</label><select class="form-select" name="department_id"><?php foreach($departments as $d):?><option value="<?=$d['id']?>" <?=((int)($_POST['department_id']??$b['department_id'])===$d['id'])?'selected':''?>><?=e($d['name'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Category</label><select class="form-select" name="category_id"><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=((int)($_POST['category_id']??$b['category_id'])===$c['id'])?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" rows="4" name="description" required><?=e($_POST['description']??$b['description'])?></textarea></div><div class="col-md-6"><label class="form-label">Allocated Amount</label><input class="form-control" type="number" step="0.01" min=".01" name="allocated_amount" value="<?=e($_POST['allocated_amount']??$b['allocated_amount'])?>" required></div><div class="col-12"><button class="btn btn-primary">Update & Resubmit</button></div></div></form></div></div><?php require ROOT_PATH.'/includes/footer.php';?>
